import { Toaster as Sonner, type ToasterProps } from "sonner";
import { X } from "lucide-react";
import { cn } from "@/lib/cn";
import { Loader } from "./loader.js";
import { Status } from "./status.js";
import { createPortal } from "react-dom";
import { useOverlayRoot } from "@/components/ui/overlay-root";

import { toast } from "sonner";

export { toast };

/**
 * Show a notice a hosted App asked for, on one named Toaster, with the
 * notice's tone choosing the Caps status dot.
 */
export function showNotice(
  notice: Readonly<{
    message: string;
    tone?: "error" | "info" | "success" | "warning";
  }>,
  toasterId: string,
): void {
  const options = { toasterId, closeButton: true };
  if (notice.tone === undefined) toast(notice.message, options);
  else toast[notice.tone](notice.message, options);
}

/**
 * Sonner owns gestures, stacking, focus and lifetime; Caps owns the surface.
 * Colors come from the Stipe tokens in the cascade, so a `data-theme` switch
 * restyles open toasts; Sonner's own light and dark palettes are overridden.
 */
export function Toaster({ className, ...props }: ToasterProps) {
  const root = useOverlayRoot("toast");
  if (!root) return null;
  return createPortal(
    <Sonner
      position="top-right"
      swipeDirections={["right", "top"]}
      offset={16}
      gap={8}
      icons={{
        close: <X aria-hidden="true" size={12} />,
        success: <Status glyph="dot" tone="success" />,
        error: <Status glyph="dot" tone="error" />,
        warning: <Status glyph="dot" tone="warning" />,
        info: <Status glyph="dot" tone="info" />,
        loading: (
          <Loader decorative size="sm" tone="current" variant="wander" />
        ),
      }}
      className={cn("caps-toaster", className)}
      {...props}
    />,
    root,
  );
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  type ReactNode,
} from "react";

/** Semantic destinations; the host owns their paint order and positioning. */
export type OverlayLayer = "popover" | "dialog" | "toast" | "tooltip";
/** Host portal roots; null keeps an overlay waiting until its layer mounts. */
export type OverlayContainers = Readonly<
  Record<OverlayLayer, HTMLElement | null>
>;

const DismissContext = createContext<
  ((listener: () => void) => () => void) | undefined
>(undefined);

const Context = createContext<OverlayContainers | null>(null);

/** Supply shell portal roots without teaching Caps about the shell's layout. */
export function OverlayRoot({
  containers,
  children,
  subscribeDismiss,
}: {
  containers: OverlayContainers;
  children?: ReactNode;
  /** Subscribe to the host losing focus to a child surface or another window. */
  subscribeDismiss?: (listener: () => void) => () => void;
}) {
  return (
    <Context.Provider value={containers}>
      <DismissContext.Provider value={subscribeDismiss}>
        {children}
      </DismissContext.Provider>
    </Context.Provider>
  );
}

/** Wait for a provided root; standalone overlays use the current document body. */
export function useOverlayRoot(layer: OverlayLayer): HTMLElement | null {
  const containers = useContext(Context);
  if (containers !== null) return containers[layer];
  return Object.hasOwn(globalThis, "document") ? document.body : null;
}

/** Retire a transient overlay when its owning host requests light dismissal. */
export function useOverlayDismiss(dismiss: () => void): void {
  const subscribe = useContext(DismissContext);
  const callback = useRef(dismiss);
  callback.current = dismiss;
  useEffect(
    () =>
      subscribe?.(() => {
        callback.current();
      }),
    [subscribe],
  );
}

